import { isUndefined } from 'lodash-es';
import React, { forwardRef, PropsWithChildren } from 'react';

import { scrollWrapper } from './AnnotationsAtom.sty.js';
import { TracksRenderer } from './components/TracksRenderer.js';
import { DEFAULT_LABELS_WIDTH, SCROLLBAR_THRESHOLD } from './constants.js';
import { AnnotationsContext } from './context.js';
import { extractVisibleTracks } from './functions/extract-visible-tracks.js';
import { getAnnotationsTracksHeight } from './functions/get-annotations-tracks-height.js';
import { uuidv4 } from '../../../../core/utils/uuidv4.js';

/**
 * @internal
 * Props for AnnotationsAtom, representing properties related to annotations.
 */
export interface AnnotationsAtomProps {
  /** Width of the annotations' container. */
  width: number;
  /** Height of the annotations' container. */
  height?: number;
  /**
   * Optional flag to determine whether to display labels.
   * @defaultValue true
   */
  showLabels?: boolean;
  /**
   * Optional width for the labels if displayed.
   * @defaultValue 'DEFAULT_LABELS_WIDTH' constant
   */
  labelsWidth?: number;
}

/**
 * @internal
 * The Annotations atomic component
 **/
export const AnnotationsAtom = /* @__PURE__ */ forwardRef<
  SVGSVGElement,
  PropsWithChildren<AnnotationsAtomProps>
>((props, forwardedRef) => {
  const {
    width,
    height,
    children,
    showLabels = true,
    labelsWidth = DEFAULT_LABELS_WIDTH,
  } = props;

  const trackWidth = width - labelsWidth;
  const tracks = extractVisibleTracks(children);
  const tracksQuantity = React.Children.count(tracks);
  const totalTracksHeight = getAnnotationsTracksHeight(tracksQuantity);

  const applyScroll = !isUndefined(height) && totalTracksHeight > height;
  const fullWidth = width + SCROLLBAR_THRESHOLD;

  const clipPathId = `track-limit-${uuidv4()}`;

  return (
    <AnnotationsContext.Provider
      value={{ showLabels, labelsWidth, trackWidth, clipPathId }}
    >
      <div
        data-testid={'annotations-atom'}
        className={scrollWrapper({ applyScroll })}
        style={{
          width: fullWidth,
          height,
        }}
      >
        <svg
          width={width}
          height={totalTracksHeight}
          ref={forwardedRef}
          style={{ overflow: 'visible', backgroundColor: 'transparent' }}
        >
          <clipPath id={clipPathId}>
            <rect width={width} height={totalTracksHeight} />
          </clipPath>
          <TracksRenderer tracks={tracks} />
        </svg>
      </div>
    </AnnotationsContext.Provider>
  );
});

AnnotationsAtom['displayName'] = 'Annotations';
